await writeProjectFile(specPath, `
// Week 1, Day 5 — the assertions gap. Both tests log in with the SAME wrong
// password. Only one of them actually checks anything.
import { test, expect } from "@playwright/test";

test("logs in with a wrong password — and nothing checks the outcome", async ({ page }) => {
  await page.goto("/");
  await page.getByPlaceholder("Enter Email").fill("leela@gmail.com");
  await page.getByPlaceholder("Enter Password").fill("ThisIsWrong123!");
  await page.getByRole("button", { name: "Login" }).click();
  // No expect() at all. Whatever happened, this test reports green.
});

test("logs in with a wrong password — and this time we check", async ({ page }) => {
  await page.goto("/");
  await page.getByPlaceholder("Enter Email").fill("leela@gmail.com");
  await page.getByPlaceholder("Enter Password").fill("ThisIsWrong123!");
  await page.getByRole("button", { name: "Login" }).click();
  await expect(page).toHaveURL(/dashboard/, { timeout: 5000 });
});
`.trim());

await runSpec(specPath);

