await writeProjectFile(specPath, `
import { test, expect, type Locator, type Page } from "@playwright/test";

// The same login flow from day5_2, given a name and some structure.
// No assertions in here — the page object exposes locators and one action;
// the test below decides what should be true.
class LoginPage {
  readonly page: Page;
  readonly emailBox: Locator;
  readonly passwordBox: Locator;
  readonly loginButton: Locator;

  constructor(page: Page) {
    this.page = page;
    this.emailBox = page.getByPlaceholder("Enter Email");
    this.passwordBox = page.getByPlaceholder("Enter Password");
    this.loginButton = page.getByRole("button", { name: "Login" });
  }

  async signIn(email: string, password: string) {
    await this.page.goto("/");
    await this.emailBox.fill(email);
    await this.passwordBox.fill(password);
    await this.loginButton.click();
  }
}

test("LoginPage.signIn with valid credentials reaches the dashboard", async ({ page }) => {
  const loginPage = new LoginPage(page);
  await loginPage.signIn("leela@gmail.com", "Leela@123");
  await expect(page).toHaveURL(/dashboard/);
  await expect(page.getByText("Leela")).toBeVisible();
});

test("LoginPage.signIn with a wrong password stays on the login page", async ({ page }) => {
  const loginPage = new LoginPage(page);
  await loginPage.signIn("leela@gmail.com", "WrongPassword1!");
  await expect(page.getByPlaceholder("Enter Email")).toBeVisible();
  await expect(page).not.toHaveURL(/dashboard/);
});
`.trim());

await runSpec(specPath);

